import{_ as a,o as e,c as n,a2 as s}from"./chunks/framework.BXzK3EA4.js";const c=JSON.parse('{"title":"HTTP 协议演进:从 0.9 到 HTTP/3","description":"这一篇只讲主线:每个版本是为了解决上一代的什么问题而生的。 机制细节另有专篇,不要在本篇展开: - HTTP/1.1 的问题与浏览器端的绕行手段 → HTTP/1.1 队头阻塞与绕行手段 - HTTP/2 的分帧 / 多路复用 / HP","frontmatter":{},"headers":[],"relativePath":"网络/2-http-evolution.md","filePath":"网络/2-http-evolution.md","lastUpdated":1793930980000}'),o={name:"网络/2-http-evolution.md"};function r(d,t,l,i,p,T){return e(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="http-协议演进-从-0-9-到-http-3" tabindex="-1">HTTP 协议演进:从 0.9 到 HTTP/3 <a class="header-anchor" href="#http-协议演进-从-0-9-到-http-3" aria-label="Permalink to &quot;HTTP 协议演进:从 0.9 到 HTTP/3&quot;">​</a></h1><blockquote><p><strong>这一篇只讲主线</strong>:每个版本是为了解决上一代的什么问题而生的。</p><p>机制细节另有专篇,不要在本篇展开:</p><ul><li>HTTP/1.1 的问题与浏览器端的绕行手段 → <a href="./3-http1-problems">HTTP/1.1 队头阻塞与绕行手段</a></li><li>HTTP/2 的分帧 / 多路复用 / HPACK 怎么工作 → <a href="./4-http2">HTTP/2 机制:分帧、多路复用与 HPACK</a></li><li>HTTP/3 与 QUIC → <a href="./13-http3">HTTP/3 与 QUIC 深度</a></li><li>报文结构 → <a href="./6-message">HTTP 报文结构</a></li></ul></blockquote><h2 id="一、一条主线-让「同一条连接上并行跑多个请求」" tabindex="-1">一、一条主线:让「同一条连接上并行跑多个请求」 <a class="header-anchor" href="#一、一条主线-让「同一条连接上并行跑多个请求」" aria-label="Permalink to &quot;一、一条主线:让「同一条连接上并行跑多个请求」&quot;">​</a></h2><p>Web 的演进史本质上是一条<strong>并发能力主线</strong>:</p><table tabindex="0"><thead><tr><th>版本</th><th>传输层</th><th>同一连接能否并行</th><th>队头阻塞</th><th>它真正解决的问题</th></tr></thead><tbody><tr><td>HTTP/0.9</td><td>TCP</td><td>❌ 一次一个</td><td>—</td><td>能取到页面</td></tr><tr><td>HTTP/1.0</td><td>TCP</td><td>❌ 一次一个</td><td>应用层</td><td>能带元数据(头、状态码)</td></tr><tr><td>HTTP/1.1</td><td>TCP</td><td>❌ 一次一个</td><td>应用层</td><td>连接可复用 + 虚拟主机</td></tr><tr><td>HTTP/2</td><td>TCP</td><td>✅ 多流</td><td>传输层</td><td>把并行收回协议层</td></tr><tr><td>HTTP/3</td><td>QUIC(UDP)</td><td>✅ 独立流</td><td>无</td><td>把并行下沉到传输层</td></tr></tbody></table><p><strong>每次演进都是同一件事</strong>:HTTP/1.1 用「<strong>多开连接</strong>」绕开并行限制,HTTP/2 用「<strong>一条连接多流</strong>」正面解决,HTTP/3 再把并行的粒度下沉到<strong>每条流独立重传</strong>。</p><h2 id="二、http-0-9-1991-能取到页面就行" tabindex="-1">二、HTTP/0.9(1991):能取到页面就行 <a class="header-anchor" href="#二、http-0-9-1991-能取到页面就行" aria-label="Permalink to &quot;二、HTTP/0.9(1991):能取到页面就行&quot;">​</a></h2><p><strong>极简设计</strong>:</p><ul><li>只有 <code>GET</code> 方法</li><li>响应只能是 HTML</li><li>没有头、没有状态码</li><li>传输完就关闭连接</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>客户端:GET /</span></span>
<span class="line"><span>服务器:&lt;html&gt;&lt;body&gt;Hello World&lt;/body&gt;&lt;/html&gt;</span></span>
<span class="line"><span>连接关闭</span></span></code></pre></div><p><strong>当时的 Web</strong> 就是一堆互相链接的静态 HTML,这个设计完全够用。</p><h2 id="三、http-1-0-1996-rfc-1945-能带元数据了" tabindex="-1">三、HTTP/1.0(1996, RFC 1945):能带元数据了 <a class="header-anchor" href="#三、http-1-0-1996-rfc-1945-能带元数据了" aria-label="Permalink to &quot;三、HTTP/1.0(1996, RFC 1945):能带元数据了&quot;">​</a></h2><p><strong>核心改进</strong>:</p><ul><li>引入 <code>POST</code>、<code>HEAD</code> 方法</li><li>引入 HTTP 头(<code>Content-Type</code>、<code>Authorization</code>、<code>User-Agent</code>)</li><li>引入状态码(<code>200</code>、<code>404</code>、<code>500</code>)</li><li>引入版本号</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /index.html HTTP/1.0</span></span>
<span class="line"><span>User-Agent: Mozilla/1.0</span></span>
<span class="line"><span>Accept: text/html</span></span>
<span class="line"><span></span></span>
<span class="line"><span>HTTP/1.0 200 OK</span></span>
<span class="line"><span>Content-Type: text/html</span></span>
<span class="line"><span>Content-Length: 123</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&lt;html&gt;...&lt;/html&gt;</span></span></code></pre></div><p><strong>遗留问题</strong>:</p><ul><li><strong>每个请求都要新建 TCP 连接</strong>(3 次握手 + 慢启动)</li><li>一个 HTML 引用 10 个 JS/CSS → 10 次连接建立,大量时间浪费在握手和慢启动上</li></ul><blockquote><p>这一条直接催生了 HTTP/1.1 的持久连接。</p></blockquote><h2 id="四、http-1-1-1999-rfc-2068-2616-让连接能被复用" tabindex="-1">四、HTTP/1.1(1999, RFC 2068 / 2616):让连接能被复用 <a class="header-anchor" href="#四、http-1-1-1999-rfc-2068-2616-让连接能被复用" aria-label="Permalink to &quot;四、HTTP/1.1(1999, RFC 2068 / 2616):让连接能被复用&quot;">​</a></h2><p>HTTP/1.1 至今仍是最广泛使用的版本,它有五个关键改动。</p><h3 id="_4-1-持久连接-keep-alive" tabindex="-1">4.1 持久连接(Keep-Alive) <a class="header-anchor" href="#_4-1-持久连接-keep-alive" aria-label="Permalink to &quot;4.1 持久连接(Keep-Alive)&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>默认 Connection: keep-alive</span></span>
<span class="line"><span>同一个 TCP 连接可以连续发多个请求</span></span></code></pre></div><p><strong>省掉了每个请求一次的 TCP 握手 + TLS 握手</strong>,这是当时最大的性能收益。</p><h3 id="_4-2-host-头与虚拟主机" tabindex="-1">4.2 Host 头与虚拟主机 <a class="header-anchor" href="#_4-2-host-头与虚拟主机" aria-label="Permalink to &quot;4.2 Host 头与虚拟主机&quot;">​</a></h3><p><code>Host</code> 头让<strong>一个 IP 可以承载多个域名</strong>,虚拟主机成为可能——这是今天「一台服务器跑几百个站点」的前提。</p><h3 id="_4-3-分块传输-chunked" tabindex="-1">4.3 分块传输(Chunked) <a class="header-anchor" href="#_4-3-分块传输-chunked" aria-label="Permalink to &quot;4.3 分块传输(Chunked)&quot;">​</a></h3><p><code>Transfer-Encoding: chunked</code>:响应长度未知时也能边生成边传输,不必先算好 <code>Content-Length</code>。</p><h3 id="_4-4-缓存与范围请求" tabindex="-1">4.4 缓存与范围请求 <a class="header-anchor" href="#_4-4-缓存与范围请求" aria-label="Permalink to &quot;4.4 缓存与范围请求&quot;">​</a></h3><ul><li><code>ETag</code> / <code>If-None-Match</code>、<code>Last-Modified</code> / <code>If-Modified-Since</code> → 协商缓存</li><li><code>Range</code> → 字节范围请求,支持断点续传与视频拖拽</li></ul><h3 id="_4-5-遗留问题-管线化与队头阻塞" tabindex="-1">4.5 遗留问题:管线化与队头阻塞 <a class="header-anchor" href="#_4-5-遗留问题-管线化与队头阻塞" aria-label="Permalink to &quot;4.5 遗留问题:管线化与队头阻塞&quot;">​</a></h3><p>HTTP/1.1 还有<strong>管线化(pipelining)</strong>:不等响应就发下一个请求。但因为<strong>响应必须按请求顺序返回</strong>,服务端要维护一个有序队列,实现复杂且容易让慢请求堵住整条连接,所以<strong>浏览器几乎从不启用</strong>。</p><p>于是 HTTP/1.1 落进一个尴尬境地:</p><ul><li>一条连接上只能有一个请求在途 → <strong>应用层队头阻塞</strong></li><li>浏览器只好<strong>对同一域名开 6 条连接</strong>来绕开</li></ul><p>这套 workaround 的细节、代价,以及 HTTP/2 如何把它收回协议层,见 <a href="./3-http1-problems">HTTP/1.1 队头阻塞与绕行手段</a>。</p><h2 id="五、http-2-2015-rfc-7540-把并行收回协议层" tabindex="-1">五、HTTP/2(2015, RFC 7540):把并行收回协议层 <a class="header-anchor" href="#五、http-2-2015-rfc-7540-把并行收回协议层" aria-label="Permalink to &quot;五、HTTP/2(2015, RFC 7540):把并行收回协议层&quot;">​</a></h2><p><strong>目标</strong>:解决 HTTP/1.1 的队头阻塞,<strong>但不改变 HTTP 语义</strong>——方法、状态码、头字段的语义完全不变,变的只是传输格式。</p><p>四项核心改进(机制见 <a href="./4-http2">HTTP/2 机制:分帧、多路复用与 HPACK</a>):</p><table tabindex="0"><thead><tr><th>改进</th><th>解决的问题</th></tr></thead><tbody><tr><td><strong>二进制分帧</strong></td><td>文本协议无法高效解析;帧带 stream id 才能乱序</td></tr><tr><td><strong>多路复用</strong></td><td>一条连接上并行跑几十上百个流,不再需要 6 连接 workaround</td></tr><tr><td><strong>头部压缩(HPACK)</strong></td><td>每次请求都带完整头太浪费,重复头只发索引</td></tr><tr><td><strong>流优先级</strong></td><td>让关键资源优先传输</td></tr></tbody></table><p><strong>效果</strong>:一次页面加载从「6 连接 × 5 批」变成「1 连接 × 30 流」。</p><p><strong>遗留问题</strong>:传输层仍是 TCP。TCP 是字节流,<strong>丢一个包后面所有字节都得等重传</strong>,所有流一起卡住。这叫<strong>传输层队头阻塞</strong>,HTTP/2 解决不了。</p><h2 id="六、http-3-2022-rfc-9114-换掉传输层" tabindex="-1">六、HTTP/3(2022, RFC 9114):换掉传输层 <a class="header-anchor" href="#六、http-3-2022-rfc-9114-换掉传输层" aria-label="Permalink to &quot;六、HTTP/3(2022, RFC 9114):换掉传输层&quot;">​</a></h2><p><strong>核心改变</strong>:抛弃 TCP,基于 <strong>QUIC</strong>(Quick UDP Internet Connections)。</p><p><strong>为什么必须换传输层</strong>:</p><ul><li><strong>TCP 改不动</strong>:改 TCP 需要操作系统升级,部署周期以年计</li><li><strong>TCP 层队头阻塞</strong>在 HTTP/2 时代成为主要瓶颈</li><li><strong>握手太慢</strong>:TCP + TLS 1.2 需要 5 个 RTT</li></ul><p><strong>QUIC 的四个关键收益</strong>(细节见 <a href="./13-http3">HTTP/3 与 QUIC 深度</a>):</p><ol><li><strong>0-RTT / 1-RTT 握手</strong>——首次连接 1-RTT,复用连接可 0-RTT</li><li><strong>独立流</strong>——每条流独立 ACK 与重传,一个流丢包不阻塞其他流(<strong>彻底解决传输层队头阻塞</strong>)</li><li><strong>内置 TLS 1.3</strong>——无法禁用,顺带统一了加密基线</li><li><strong>连接迁移</strong>——用 64-bit Connection ID 标识连接,手机切 WiFi 时 IP 变了也不断连</li></ol><p><strong>现状</strong>:主流浏览器与 CDN 均已支持,Nginx 1.25+ 提供 <code>http3 on</code>。</p><h2 id="七、全景对比" tabindex="-1">七、全景对比 <a class="header-anchor" href="#七、全景对比" aria-label="Permalink to &quot;七、全景对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>特性</th><th>HTTP/1.1</th><th>HTTP/2</th><th>HTTP/3</th></tr></thead><tbody><tr><td>传输层</td><td>TCP</td><td>TCP</td><td>QUIC(UDP)</td></tr><tr><td>报文格式</td><td>文本</td><td>二进制分帧</td><td>二进制分帧</td></tr><tr><td>多路复用</td><td>❌</td><td>✅ 同连接多流</td><td>✅ 独立流</td></tr><tr><td>头部压缩</td><td>❌</td><td>HPACK</td><td>QPACK</td></tr><tr><td>握手</td><td>TCP + TLS</td><td>TCP + TLS</td><td>内置 TLS 1.3(0/1-RTT)</td></tr><tr><td>队头阻塞</td><td>应用层 + 传输层</td><td>仅传输层</td><td>无</td></tr><tr><td>服务器推送</td><td>❌</td><td>✅(已弃用)</td><td>✅</td></tr><tr><td>连接迁移</td><td>❌</td><td>❌</td><td>✅</td></tr><tr><td>强制 TLS</td><td>❌</td><td>✅</td><td>✅</td></tr><tr><td>部署难度</td><td>低</td><td>中</td><td>中</td></tr></tbody></table><h2 id="八、实战选型" tabindex="-1">八、实战选型 <a class="header-anchor" href="#八、实战选型" aria-label="Permalink to &quot;八、实战选型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>新项目:Nginx 开启 HTTP/2(基本免费),HTTP/3 视 CDN 与网络情况</span></span>
<span class="line"><span>老项目:升级 Nginx 并启用 HTTP/2,收益最明显</span></span>
<span class="line"><span>高延迟 / 移动网络:HTTP/3 收益最大</span></span>
<span class="line"><span>弱网 / 丢包率高:HTTP/3 优势明显</span></span>
<span class="line"><span>内网应用:HTTP/1.1 也完全够用</span></span></code></pre></div><p><strong>关键提醒</strong>:HTTP/2 时代,那些「为 HTTP/1.1 设计的优化」很多变成了<strong>反模式</strong>——雪碧图、域名分片、内联大段 CSS/JS。详见 <a href="./3-http1-problems">HTTP/1.1 队头阻塞与绕行手段</a> 的实战部分。</p><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><h3 id="q1-http-0-9-到-1-1-的关键改进分别是什么" tabindex="-1">Q1:HTTP/0.9 到 1.1 的关键改进分别是什么? <a class="header-anchor" href="#q1-http-0-9-到-1-1-的关键改进分别是什么" aria-label="Permalink to &quot;Q1:HTTP/0.9 到 1.1 的关键改进分别是什么?&quot;">​</a></h3><ul><li><strong>0.9</strong>:只有 GET,无 header 无状态码,只能传 HTML</li><li><strong>1.0</strong>:加了状态码、<code>Content-Type</code>、<code>Content-Length</code>,支持 POST</li><li><strong>1.1</strong>(至今最广泛):<strong>持久连接</strong>(默认 keep-alive)、<strong>Host 头</strong>(虚拟主机的前提)、<strong>分块传输 chunked</strong>、缓存指令、<code>Range</code> 范围请求</li><li><strong>2</strong>:二进制分帧 + 多路复用 + 头部压缩 → <a href="./4-http2">HTTP/2 专题</a></li><li><strong>3</strong>:换到 QUIC(UDP),解决 TCP 层队头阻塞 → <a href="./13-http3">HTTP/3 专题</a></li></ul><p><strong>本质线索</strong>:1.1 的每一项改进,都在解决「同一条连接上多个请求互相拖累」或「同一个 IP 上多个站点互相冲突」这两个问题。</p><h3 id="q2-为什么-http-1-1-默认-keep-alive-这带来了什么新问题" tabindex="-1">Q2:为什么 HTTP/1.1 默认 keep-alive?这带来了什么新问题? <a class="header-anchor" href="#q2-为什么-http-1-1-默认-keep-alive-这带来了什么新问题" aria-label="Permalink to &quot;Q2:为什么 HTTP/1.1 默认 keep-alive?这带来了什么新问题?&quot;">​</a></h3><p>默认持久连接后,发第二个请求就不用重新 TCP 握手,<strong>省掉一个 RTT</strong>。</p><p><strong>新问题是队头阻塞</strong>:一条连接上 HTTP/1.1 只能有一个请求在途,第一个响应没回来,后面全排队。浏览器的应对是<strong>对同一域名开 6 条连接</strong>,但这又撞上了每域并发连接数上限。</p><p>所以 HTTP/2 的多路复用不是「优化」,是<strong>把 HTTP/1.1 的这个 workaround 收回协议层</strong>。展开见 <a href="./3-http1-problems">3-http1-problems</a>。</p><h3 id="q3-http-2-和-http-3-最本质的区别是什么" tabindex="-1">Q3:HTTP/2 和 HTTP/3 最本质的区别是什么? <a class="header-anchor" href="#q3-http-2-和-http-3-最本质的区别是什么" aria-label="Permalink to &quot;Q3:HTTP/2 和 HTTP/3 最本质的区别是什么?&quot;">​</a></h3><p><strong>HTTP/2 换了传输格式,HTTP/3 换了传输层。</strong></p><ul><li>HTTP/2 仍是 TCP 上的二进制分帧,并行粒度是「流」,但底层字节流必须顺序交付 → 传输层队头阻塞仍在</li><li>HTTP/3 是 UDP 上的 QUIC,并行粒度下沉到「独立重传」 → 彻底消除传输层队头阻塞</li></ul><p>一句话:<strong>HTTP/2 解决应用层队头阻塞,HTTP/3 解决传输层队头阻塞</strong>。</p><blockquote><p>HTTP 报文长什么样 → <a href="./6-message">HTTP 报文结构</a></p></blockquote><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>演进主线只有一条:<strong>让同一条连接上并行跑多个请求</strong>。1.1 用多连接绕开,2 用多路复用正面解决,3 用 QUIC 把并行下沉到每条流。</li><li>HTTP/1.1 五个关键改动:持久连接、Host 头(虚拟主机前提)、分块传输、缓存指令、范围请求。</li><li>keep-alive 省掉一个 RTT,却引入了应用层队头阻塞,浏览器只能靠「同域名 6 连接」绕——这是 HTTP/2 存在的直接原因。</li><li>HTTP/2 换的是<strong>传输格式</strong>,HTTP/3 换的是<strong>传输层</strong>,这是两者最本质的区别。</li><li>机制别混:HTTP/1.1 的问题看 <a href="./3-http1-problems">3</a>,HTTP/2 的实现看 <a href="./4-http2">4</a>,QUIC 看 <a href="./13-http3">13</a>。</li></ul><h2 id="九、参考文献" tabindex="-1">九、参考文献 <a class="header-anchor" href="#九、参考文献" aria-label="Permalink to &quot;九、参考文献&quot;">​</a></h2><ul><li><a href="https://http2-explained.readthedocs.io/" target="_blank" rel="noreferrer">HTTP/2 详解</a> —— Daniel Stenberg</li><li><a href="https://http3-explained.haxx.se/" target="_blank" rel="noreferrer">HTTP/3 explained</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc9114" target="_blank" rel="noreferrer">RFC 9114 (HTTP/3)</a></li><li>《HTTP 权威指南》</li></ul>`,69)])])}const g=a(o,[["render",r]]);export{c as __pageData,g as default};
